source("R/platform-load.R",encoding="UTF-8");brohn_load(ui=TRUE)
checks<-character();check<-function(label,x){stopifnot(isTRUE(x));checks<<-c(checks,label);cat("PASS",label,"\n")}
rejects<-function(x)inherits(try(force(x),silent=TRUE),"try-error")
choose<-function(x,rate=8000,first=0,stop=32000)brohn_media_cursor_seconds(x,rate,first,stop)
for(row in list(c("0",0),c("1",8000),c("1.000062499",8000),c("1.0000625",8001),c("1.000062501",8001),c("3.999875",31999)))
  check(paste("Original8kHz oracle",row[[1]]),choose(row[[1]])$sample==as.numeric(row[[2]]))
check("Exact half-sample tie rounds later without floating epsilon",choose("0.0005",1000,0,1000)$sample==1L)
check("Awkward44.1kHz decimal resolves nearest original sample",choose("0.000022676",44100,0,44100)$sample==1L)
check("Highest supported rate keeps nine-place integer remainder exact",choose("1.000003906",384000,0,768000)$sample==384001L&&choose("1.000003907",384000,0,768000)$sample==384002L)
check("Saved partial-window beginning remains exact",choose("0.1",1000,100,200)$sample==100L)
for(x in c("-1","1e-3","NaN","1.0000000001","",".5","4","4.1"))check(paste("Unsupported or end-exclusive position",x),rejects(choose(x)))
check("Before-window time cannot round into an unrelated saved interval",rejects(choose("0.09999",1000,100,200)))
check("Last half-sample cannot snap past the saved end",rejects(choose("0.1995",1000,100,200)))
check("Cursor policy and resolved original time are disclosed",identical(choose("1.0000625")$policy,"nearest_original_sample_half_ties_later")&&identical(choose("1.0000625")$time_s,"1.000125"))
args<-commandArgs(trailingOnly=TRUE);if(length(args))brohn_write_json_file(list(passed=TRUE,checks=as.list(checks)),args[[1]])
cat(length(checks),"cursor checks passed\n")
